"""Reviewed Core Presence and remaining Protean powers, PDF 268–273."""
import runpy
from pathlib import Path
base=runpy.run_path(str(Path(__file__).with_name('review-core-disciplines.py')))
add=base['add']
add('daunt','Daunt','Presença',1,[268],[
('Descrição','Uma aura ameaçadora repele mortais e faz vampiros hesitarem antes de agir contra o usuário.'),('Custo','Gratuito.'),('Sistema','Some Presença às rolagens de Intimidação. Atacar o usuário exige Determinação + Autocontrole, Dificuldade 2. Não pode usar simultaneamente com Fascínio.'),('Duração','Uma cena ou até encerrar voluntariamente.')],[
('Descrição','A threatening aura repels mortals and makes vampires hesitate before acting against the user.'),('Custo','Free.'),('Sistema','Add Presence to Intimidation rolls. Attacking the user requires Resolve + Composure, Difficulty 2. Cannot be used simultaneously with Awe.'),('Duração','One scene or until voluntarily ended.')])
add('awe','Awe','Presença',1,[268,269],[
('Descrição','Atrai atenção e torna quem o escuta mais receptivo, sem causar paixão arrebatadora. Ao terminar, as opiniões anteriores retornam.'),('Custo','Gratuito.'),('Parada','Manipulação + Presença contra Autocontrole + Inteligência de quem percebe a influência e tenta resistir.'),('Sistema','Some Presença a testes de Persuasão ou Performance e, a critério do Narrador, outras rolagens ligadas a Carisma. Quem sabe estar sendo afetado pode resistir no conflito acima: vitória o protege pela cena; crítico, pela noite. Não pode usar simultaneamente com Amedrontar.'),('Duração','Uma cena ou até encerrar voluntariamente.')],[
('Descrição','Draws attention and makes listeners more receptive without overwhelming infatuation. Their former opinions return when it ends.'),('Custo','Free.'),('Parada','Manipulation + Presence opposed by Composure + Intelligence for someone aware of the influence who tries to resist.'),('Sistema','Add Presence to Persuasion or Performance tests and, at the Storyteller’s discretion, other Charisma-related rolls. Someone aware of being affected may resist with the contest above: a win protects for the scene; a critical for the night. Cannot be used simultaneously with Daunt.'),('Duração','One scene or until voluntarily ended.')])
add('lingering-kiss','Lingering Kiss','Presença',2,[269],[
('Descrição','Torna o Beijo fortalecedor e viciante. A vítima pode perseguir o usuário por nova alimentação, colocando-o em risco de Laço quando a vítima é vampira.'),('Custo','Gratuito.'),('Sistema','Escolha ativar a cada alimentação que sacie ao menos 1 Fome. A vítima escolhe um Atributo Social e recebe bônus igual à metade da Presença do usuário, arredondada para cima, por uma noite. Depois sofre abstinência: ações que não busquem nova dose recebem penalidade igual ao bônus inicial. Pode gastar Vontade para ignorar a penalidade por uma cena. A abstinência desaparece após noites iguais à Presença do usuário. Usuário Enlaçado só pode afetar mortais, não vampiros. Vampiros com a Qualidade À Prova de Laço não podem adquirir este poder.'),('Duração','Bônus por uma noite; duração indicada do poder: noites iguais à Presença, com a abstinência descrita acima.')],[
('Descrição','Makes the Kiss empowering and addictive. A victim may pursue the user for another feeding, risking a Blood Bond when the victim is a vampire.'),('Custo','Free.'),('Sistema','Choose whether to activate at each feeding that slakes at least 1 Hunger. The victim chooses a Social Attribute and gains a bonus equal to half the user’s Presence, rounded up, for one night. Withdrawal then penalizes all actions not seeking another dose by the same amount. Willpower can ignore the penalty for one scene. Withdrawal ends after nights equal to the user’s Presence. A Blood Bound user can affect mortals only, not vampires. Vampires with the Unbondable Merit cannot acquire this power.'),('Duração','One-night bonus; the listed power duration is nights equal to Presence, with withdrawal as described above.')],aliases=['Beijo Indelével'])
add('dread-gaze','Dread Gaze','Presença',3,[269],[
('Descrição','Mostra presas e expressão predatória para aterrorizar um alvo mortal ou vampiro.'),('Custo','Um Teste de Sangue.'),('Parada','Carisma + Presença contra Autocontrole + Determinação.'),('Sistema','Falha: mortal recua e só pode defender-se por um turno; vampiro não é afetado. Vitória: mortal foge; vampiro só pode defender-se por um turno, a menos que gaste Vontade igual à margem do usuário, mínimo 1. Crítico: mortal congela ou se encolhe em posição fetal; vampiro testa Frenesi de Terror, Dificuldade 3, e mesmo se resistir sofre os efeitos de uma vitória normal.'),('Duração','Um turno.')],[
('Descrição','Bares fangs and a predatory expression to terrify one mortal or vampire.'),('Custo','One Rouse Check.'),('Parada','Charisma + Presence opposed by Composure + Resolve.'),('Sistema','Failure: a mortal recoils and can only defend for one turn; a vampire is unaffected. Win: a mortal flees; a vampire can only defend for one turn unless spending Willpower equal to the user’s margin, minimum 1. Critical: a mortal freezes or curls into a fetal position; a vampire tests terror frenzy, Difficulty 3, and even on resistance suffers the ordinary-win effects.'),('Duração','One turn.')])
add('entrancement','Entrancement','Presença',3,[269,270],[
('Descrição','Concentra atração sobrenatural numa pessoa, que procura agradar o usuário sem ferir a si ou a entes queridos.'),('Custo','Um Teste de Sangue.'),('Parada','Carisma + Presença contra Autocontrole + Raciocínio.'),('Sistema','Ganhe a atenção e vença o conflito. Some Presença às paradas Sociais contra o alvo. Pode renovar indefinidamente, mas falha encerra o poder e torna o alvo imune pelo resto da noite. Pedidos de dano evidente ao alvo ou entes queridos, ou contrários aos Princípios dele, falham e exigem imediatamente novo conflito para manter o encantamento; sem mantê-lo, o efeito termina.'),('Duração','Uma hora mais uma por ponto de margem.')],[
('Descrição','Focuses supernatural attraction on one person, who seeks to please the user without harming themselves or loved ones.'),('Custo','One Rouse Check.'),('Parada','Charisma + Presence opposed by Composure + Wits.'),('Sistema','Gain attention and win the contest. Add Presence to Social pools against the target. May renew indefinitely, but failure ends the power and makes the target immune for the rest of the night. Requests for obvious harm to the target or loved ones, or against their Tenets, fail and immediately require another contest to maintain the enchantment; otherwise it ends.'),('Duração','One hour plus one per point of margin.')])
add('summon','Summon','Presença',4,[270],[
('Descrição','Convoca mortal ou vampiro que já tenha sido afetado por seu Fascínio, Transe ou Majestade, ou provado seu Sangue. O alvo conhece a identidade e localização atual do convocador.'),('Custo','Um Teste de Sangue.'),('Parada','Manipulação + Presença contra Autocontrole + Inteligência.'),('Sistema','Concentre-se por cinco minutos pensando no alvo e teste. Vitória faz o alvo ouvir o chamado, podendo ou não atendê-lo. Crítico o faz chegar o mais rápido possível, salvo risco imediato ao bem-estar. Sente atração para ir, mas não assume perigo físico ou financeiro: não vende a casa, compra passagem ou falta a reunião vital, embora possa faltar ao trabalho ou compromisso social. Pode repetir noite após noite, inclusive para alvos distantes ou relutantes.'),('Duração','Uma noite; depois a influência diminui.')],[
('Descrição','Calls a mortal or vampire previously affected by your Awe, Entrancement or Majesty, or who has tasted your Blood. The target knows the summoner’s identity and current location.'),('Custo','One Rouse Check.'),('Parada','Manipulation + Presence opposed by Composure + Intelligence.'),('Sistema','Concentrate for five minutes on the target and roll. A win makes them hear the call, which they may or may not heed. A critical brings them as quickly as possible unless their immediate well-being is at risk. They feel drawn to come but avoid physical or financial danger: they do not sell their house, buy a ticket or miss a vital meeting, though work or social obligations may be missed. May repeat night after night for distant or reluctant targets.'),('Duração','One night, after which the influence fades.')])
add('irresistible-voice','Irresistible Voice','Presença',4,[270],[
('Descrição','A voz torna-se um canal para Dominação, dispensando contato visual.'),('Custo','Nenhum custo adicional.'),('Sistema','Basta que o alvo ouça a voz do usuário para aplicar Dominação. Não funciona com voz transmitida eletronicamente, como telefone, televisão ou interfone.'),('Duração','Passiva.')],[
('Descrição','The voice becomes a channel for Dominate, removing the need for eye contact.'),('Custo','No additional cost.'),('Sistema','Hearing the user’s voice is enough to apply Dominate. Does not work through electronically transmitted voices such as phones, televisions or intercoms.'),('Duração','Passive.')],{'Dominação':1})
add('star-magnetism','Star Magnetism','Presença',5,[270],[
('Descrição','Permite afetar pessoas por transmissão ao vivo ou telefone, mas não por imagens ou mensagens gravadas.'),('Custo','Um Teste de Sangue adicional ao poder usado.'),('Sistema','Fascínio, Amedrontar e Transe funcionam por transmissão ao vivo ou telefone. Para Transe, pronuncie claramente o nome da vítima, pois afeta uma pessoa por vez. Os demais espectadores acham o usuário atraente de modo apenas natural.'),('Duração','A do poder usado.')],[
('Descrição','Affects people through live broadcasts or telephone, but not recorded images or messages.'),('Custo','One additional Rouse Check beyond the power used.'),('Sistema','Awe, Daunt and Entrancement work through live broadcasts or telephone. For Entrancement, clearly speak the victim’s name because it affects one person at a time. Other viewers find the user attractive only in a mundane way.'),('Duração','As the power used.')])
add('majesty','Majesty','Presença',5,[270],[
('Descrição','Beleza, monstruosidade ou autoridade sobrenaturais deixam observadores incapazes de falar ou agir contra o usuário.'),('Custo','Dois Testes de Sangue.'),('Parada','Carisma + Presença contra Autocontrole + Determinação de quem tenta opor-se.'),('Sistema','Presentes só podem contemplar ou desviar o olhar com medo e submissão. Para agir contra o usuário, exceto por autopreservação, é preciso vencer o conflito de Autocontrole + Determinação contra Carisma + Presença. Vitória dá um turno livre mais um por ponto de margem; somente crítico resiste pela cena inteira.'),('Duração','Uma cena.')],[
('Descrição','Supernatural beauty, monstrosity or authority leaves observers unable to speak or act against the user.'),('Custo','Two Rouse Checks.'),('Parada','Charisma + Presence opposed by Composure + Resolve of someone attempting opposition.'),('Sistema','Those present can only stare or avert their gaze in fear and submission. Acting against the user, except for self-preservation, requires winning Composure + Resolve against Charisma + Presence. A win gives one free turn plus one per point of margin; only a critical resists for the entire scene.'),('Duração','One scene.')])
add('eyes-beast','Eyes of the Beast','Proteanismo',1,[271],[
('Descrição','Os olhos brilham de modo sobrenatural e permitem enxergar sem luz.'),('Custo','Gratuito.'),('Sistema','Não exige teste. Ignore penalidades visuais por escuridão, inclusive sobrenatural. Os olhos inumanos concedem +2 dados de Intimidação contra mortais.'),('Duração','Quanto desejar.')],[
('Descrição','The eyes glow supernaturally, allowing sight without light.'),('Custo','Free.'),('Sistema','No roll. Ignore visual penalties from darkness, including supernatural darkness. The inhuman eyes grant +2 Intimidation dice against mortals.'),('Duração','As long as desired.')])
add('weight-feather','Weight of the Feather','Proteanismo',1,[271],[
('Descrição','Reduz massa e densidade efetivas quase a zero. Evita certos sensores de pressão e impactos; não amplia saltos, pois a força diminui proporcionalmente.'),('Custo','Gratuito.'),('Parada','Raciocínio + Sobrevivência, Dificuldade 3, para ativar como reação, por exemplo durante uma queda; com tempo para preparar, sem teste.'),('Sistema','Enquanto ativo, é imune a dano de quedas, colisões e impacto por ser arremessado. Pode evitar dispositivos de pressão, conforme o Narrador.'),('Duração','Quanto desejar.')],[
('Descrição','Reduces effective mass and density almost to zero. Avoids some pressure sensors and impacts; does not extend leaps because strength decreases proportionally.'),('Custo','Free.'),('Parada','Wits + Survival, Difficulty 3, to activate as a reaction, such as while falling; no roll with preparation time.'),('Sistema','While active, immune to damage from falls, collisions and being thrown. May avoid pressure-triggered devices at the Storyteller’s discretion.'),('Duração','As long as desired.')])
add('feral-weapons','Feral Weapons','Proteanismo',2,[272],[
('Descrição','Alonga armas naturais em garras ou presas monstruosas.'),('Custo','Um Teste de Sangue.'),('Sistema','Sem teste de Habilidade para ativar. A arma natural torna-se arma de Briga leve e perfurante com modificador de dano +2. Mordidas vampíricas continuam causando apenas 2 danos agravados, independentemente dos sucessos, mas dispensam a penalidade de ataque localizado. Dano superficial causado por essas armas naturais não é reduzido à metade.'),('Duração','Uma cena.')],[
('Descrição','Extends natural weapons into monstrous claws or fangs.'),('Custo','One Rouse Check.'),('Sistema','No Skill roll to activate. The natural weapon becomes a light piercing Brawl weapon with a +2 damage modifier. Vampire bites still inflict only 2 Aggravated damage regardless of successes, but remove the called-shot penalty. Superficial damage inflicted by these natural weapons is not halved.'),('Duração','One scene.')])
add('shapechange','Shapechange','Proteanismo',3,[272,273],[
('Descrição','Assume uma única forma animal de massa aproximadamente igual à original, normalmente lobo, grande felino ou cobra gigante, ligada ao clã ou presas. Parece exemplar magnífico da espécie, sem sinal sobrenatural evidente.'),('Custo','Um Teste de Sangue.'),('Sistema','Sem teste. Transformar leva um turno, sem outras ações nesse turno. Recebe Atributos Físicos, sentidos, Habilidades nativas e limitações do animal (p. 373), inclusive comunicação e manipulação de objetos; muitos só carregam algo na boca. Outras Disciplinas dependem do Narrador: geralmente Auspícios, Animalismo, Celeridade, Fortitude, Potência e Proteanismo funcionam; muitos poderes de Dominação, Ofuscação e Presença são problemáticos; Feitiçaria de Sangue é impossível.'),('Duração','Uma cena ou até encerrar voluntariamente.')],[
('Descrição','Assumes one animal form of roughly the original mass, usually a wolf, large cat or giant snake associated with clan or prey. It looks like a magnificent specimen without obvious supernatural signs.'),('Custo','One Rouse Check.'),('Sistema','No roll. Transformation takes one turn with no other actions that turn. Gains the animal’s Physical Attributes, senses, native Skills and limitations (p. 373), including communication and object handling; many animals can carry something only in the mouth. Other Disciplines depend on the Storyteller: generally Auspex, Animalism, Celerity, Fortitude, Potence and Protean work; many Dominate, Obfuscate and Presence powers are problematic; Blood Sorcery is impossible.'),('Duração','One scene or until voluntarily ended.')])
add('metamorphosis','Metamorphosis','Proteanismo',4,[273],[
('Descrição','Concede uma forma animal adicional, agora permitindo mudar de tamanho, como morcego, rato, inseto extraordinariamente grande ou cobra.'),('Custo','Um Teste de Sangue.'),('Sistema','Use as regras de Mudança de Forma: um turno para transformar-se sem outras ações, recebendo características e limitações do animal; outras Disciplinas dependem do Narrador e Feitiçaria de Sangue não funciona nessa forma.'),('Duração','Uma cena ou até encerrar voluntariamente.')],[
('Descrição','Grants an additional animal form, now allowing size changes, such as a bat, rat, unusually large insect or snake.'),('Custo','One Rouse Check.'),('Sistema','Use Shapechange rules: one turn to transform with no other actions, gaining the animal’s traits and limitations; other Disciplines depend on the Storyteller and Blood Sorcery does not function in that form.'),('Duração','One scene or until voluntarily ended.')],prerequisites=['Mudança de Forma'])
add('unfettered-heart','The Unfettered Heart','Proteanismo',5,[273],[
('Descrição','O coração move-se lentamente pelo peito, dificultando estacamento e permitindo expulsar uma estaca.'),('Custo','Gratuito para a proteção; um Teste de Sangue por tentativa de expulsar a estaca.'),('Parada','Força + Determinação, Dificuldade 5, uma vez por hora para expulsar estaca; não pode tentar em Fome 5.'),('Sistema','Aumente em 3 a Dificuldade de estacamento fora de combate. Em combate com Armas Brancas, só uma vitória crítica do atacante com estaca alcança o coração. Se já estacado, vencer o teste acima expulsa a estaca e encerra a paralisia.'),('Duração','Passiva.')],[
('Descrição','The heart slowly moves within the chest, making staking harder and allowing a stake to be expelled.'),('Custo','Free protection; one Rouse Check per attempt to expel a stake.'),('Parada','Strength + Resolve, Difficulty 5, once per hour to expel a stake; cannot attempt at Hunger 5.'),('Sistema','Increase non-combat staking Difficulty by 3. In Melee combat, only a critical win by the stake-wielding attacker reaches the heart. If already staked, winning the roll above expels the stake and ends paralysis.'),('Duração','Passive.')],aliases=['Unfettered Heart'])
add('mist-form','Mist Form','Proteanismo',5,[273],[
('Descrição','Vira névoa visível que passa por canos e fendas. Ventos fortes afetam seu movimento, mas forças naturais não a dispersam.'),('Custo','De um a três Testes de Sangue.'),('Sistema','Sem teste de Habilidade. Transformar leva três turnos; cada Teste de Sangue adicional reduz em um turno. Move-se à velocidade de caminhada e percebe os arredores misticamente como no corpo original. Não fala nem faz contato visual. Só usa Disciplinas sem forma ou presença física, conforme o Narrador. Só sofre dano de luz solar, fogo e ataques sobrenaturais imateriais, como certos Rituais.'),('Duração','Uma cena ou até encerrar voluntariamente.')],[
('Descrição','Becomes visible mist that passes through pipes and cracks. Strong winds affect movement but natural forces cannot disperse it.'),('Custo','One to three Rouse Checks.'),('Sistema','No Skill roll. Transformation takes three turns; each additional Rouse Check reduces it by one turn. Moves at walking speed and mystically perceives surroundings as in the original body. Cannot speak or make eye contact. Only Disciplines requiring no physical form or presence are available, as the Storyteller decides. Only sunlight, fire and immaterial supernatural attacks such as certain Rituals inflict damage.'),('Duração','One scene or until voluntarily ended.')])
print('16 additional Core powers reviewed; the existing Earth Meld version is preserved')
